def first_bad(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []  # indices of openers still open
    for i, ch in enumerate(s):
        if ch in "([{":
            stack.append(i)
        elif ch in pairs:
            if not stack or s[stack.pop()] != pairs[ch]:
                return i
    return stack[0] if stack else -1
